import numpy as np
def _lsig(a, n):
    a = np.asarray(a, dtype=float)
    if a.shape != (n,) or not np.all(a > 0.0):
        return -1.0
    w = np.cos(np.arange(1, n + 1, dtype=float))
    return float(np.sum(np.log(a) * w) / 10.0)
def _stationary(a, kc, k):
    a = np.asarray(a, dtype=float)
    if a.shape != kc.shape or not np.all(a > 0.0):
        return 0.0
    n = a.size
    grads = []
    for m in range(n):
        g = -k[m] * (1.0 + a[m + 1:].sum()) / (kc[m] * a[m] ** 2)
        g += sum((1.0 + k[i] / a[i]) / kc[i] for i in range(m))
        grads.append(g)
    grads = np.array(grads)
    spread = np.max(np.abs(grads - grads.mean())) / np.max(np.abs(grads))
    return 1.0 if spread < 1e-9 else 0.0
def _total_sig(a, n, total):
    a = np.asarray(a, dtype=float)
    if a.shape != (n,) or not np.all(a > 0.0):
        return -1.0
    w = np.sin(np.arange(1, n + 1, dtype=float))
    shape = np.sum(np.log(a) * w) / 10.0
    closure = 100.0 * (np.sum(a) / total - 1.0)
    return float(shape + closure)
def _tangent_sig(a, n, total_mode):
    a = np.asarray(a, dtype=float)
    if a.shape != (2, n) or not np.all(np.isfinite(a)) or not np.all(a[0] > 0.0):
        return -1.0
    w = np.cos(np.arange(1, n + 1, dtype=float))
    out = np.sum(np.log(a[0]) * w) / 10.0 + np.sum(a[1] * w) / 10.0
    if total_mode:
        out += 100.0 * (np.sum(a[1]) - 1.0)
    return float(out)
KC = np.array([14.0, 26.0, 8.0, 33.0, 11.0])
KM = np.array([3.0e-4, 1.6e-3, 1.2e-4, 9.0e-4, 5.0e-4])
assert np.allclose(_lsig(propagate_optimal_levels(2.0e-3, KC.copy(), KM.copy()), 5), target)

